import { useState } from "react";
import type { AttachmentHandlerOpts } from "@sierra/web";
import { mockAttachmentOpts, reactDeclaration } from "./util";

type TimeSlot = {
    start: string;
    end?: string;
};

export type CalendarDate = {
    year: number;
    month: number;
    day: number;
    slots?: TimeSlot[];
};

export type DateTimeSelectorAttachmentPayload = {
    type: "datetime-selector";
    subtype: "date" | "time" | "datetime";
    submitLabel: string;
    dates: CalendarDate[] | null;
};

export const DateTimeSelectorDeclaration = reactDeclaration<DateTimeSelectorAttachmentPayload>({
    type: "datetime-selector",
    name: "Date and time selector",
    description: "A selector for date and time",
    schema: `{
    subtype: "date" | "time" | "datetime";
    submitLabel: string;
    dates: {
        year: number;
        month: number;
        day: number;
        slots?: {
            start: string;
            end?: string;
        }[];
    }[] | null;
}`,
    renderPreview: data => {
        const props = data ?? {
            type: "datetime-selector" as const,
            subtype: "datetime",
            submitLabel: "Submit",
            dates: Array.from({ length: 6 }).map((_v, idx) => {
                const today = new Date();
                const day = new Date(today.getFullYear(), today.getMonth(), today.getDate() + idx);
                return {
                    year: day.getFullYear(),
                    month: day.getMonth() + 1,
                    day: day.getDate(),
                    slots: [
                        { start: "9am", end: "10am" },
                        { start: "1pm", end: "2pm" },
                        { start: "3pm", end: "4pm" },
                    ],
                };
            }),
        };
        return <DateTimeSelector data={props} opts={mockAttachmentOpts()} />;
    },
    render: (data, opts) => {
        return <DateTimeSelector data={data} opts={opts} />;
    },
});

export function DateTimeSelector({
    data,
    opts,
}: {
    data: DateTimeSelectorAttachmentPayload;
    opts: AttachmentHandlerOpts;
}) {
    const { dates, submitLabel } = data;
    const [selectedDate, setSelectedDate] = useState<CalendarDate | null>(
        data.subtype === "time" && dates ? dates[0] : null
    );
    const [selectedSlot, setSelectedSlot] = useState<TimeSlot | null>(null);

    if (!opts.isLastMessage) {
        if (data.subtype === "time") {
            return <SubmittedTimeSelector data={data} />;
        }
        return <SubmittedDateTimeSelector data={data} />;
    }

    return (
        <div className="flex flex-col gap-2">
            {data.subtype !== "time" && (
                <Calendar
                    selectedDate={selectedDate}
                    dates={dates}
                    onDateSelect={date => {
                        setSelectedDate(date);
                        setSelectedSlot(null);
                    }}
                />
            )}
            {data.subtype !== "date" && selectedDate && (
                <SlotSelector
                    selectedSlot={selectedSlot}
                    date={selectedDate}
                    slots={selectedDate.slots ?? []}
                    onSlotSelect={setSelectedSlot}
                />
            )}
            {((data.subtype === "datetime" && selectedDate !== null && selectedSlot !== null) ||
                (data.subtype === "date" && selectedDate !== null) ||
                (data.subtype === "time" && selectedSlot !== null)) && (
                <div
                    style={{
                        backgroundColor: "var(--chat-color-assistant-bubble)",
                        color: "var(--chat-color-assistant-text)",
                        padding: "0.75rem",
                        borderRadius: "0.75rem",
                    }}
                    className="flex flex-row justify-between items-center animate-fade"
                >
                    <FormattedSelection selectedDate={selectedDate} selectedSlot={selectedSlot} />
                    <SubmitButton
                        label={submitLabel}
                        variant="primary"
                        onClick={() => {
                            opts.sendMessage(formatDatetime(selectedDate, selectedSlot), [
                                {
                                    type: "custom",
                                    data: JSON.stringify({
                                        type: "submit-selection",
                                        date: selectedDate,
                                        slot: selectedSlot,
                                    }),
                                },
                            ]);
                        }}
                    />
                </div>
            )}
        </div>
    );
}

function SubmittedDateTimeSelector({ data }: { data: DateTimeSelectorAttachmentPayload }) {
    return <Calendar dates={data.dates} disabled={true} />;
}

function SubmittedTimeSelector({ data }: { data: DateTimeSelectorAttachmentPayload }) {
    return (
        <SlotSelector
            selectedSlot={null}
            date={data.dates ? data.dates[0] : { year: 1, month: 1, day: 1 }}
            slots={data.dates?.[0]?.slots ? data.dates[0].slots : []}
            onSlotSelect={() => {}}
            disabled={true}
        />
    );
}

function FormattedSelection({
    selectedDate,
    selectedSlot,
}: {
    selectedDate: CalendarDate | null;
    selectedSlot: TimeSlot | null;
}) {
    return (
        <div className="flex flex-row items-center gap-2">
            <CalendarIcon />
            {formatDatetime(selectedDate, selectedSlot)}
        </div>
    );
}

function SlotSelector({
    selectedSlot,
    date,
    slots,
    onSlotSelect,
    disabled = false,
}: {
    selectedSlot: TimeSlot | null;
    date: CalendarDate;
    slots: TimeSlot[];
    onSlotSelect: (slot: TimeSlot) => void;
    disabled?: boolean;
}) {
    return (
        <div className="flex flex-row gap-2 animate-fade fadeOut">
            {slots.length === 0 && (
                <div className="text-sm text-gray-500">
                    There are no slots available for this date.
                </div>
            )}
            {slots.length > 0 && (
                <div className="flex flex-col gap-4 pt-2 pb-2">
                    <div>Here are the available slots:</div>
                    <div className="flex flex-row gap-2 flex-wrap">
                        {slots.map(slot => (
                            <SlotItem
                                key={`${date.year}-${date.month}-${date.day}-${slot.start}`}
                                slot={slot}
                                isSelected={selectedSlot === slot}
                                onSlotSelect={onSlotSelect}
                                disabled={disabled}
                            />
                        ))}
                    </div>
                </div>
            )}
        </div>
    );
}

function SlotItem({
    slot,
    isSelected,
    onSlotSelect,
    disabled = false,
}: {
    slot: TimeSlot;
    isSelected: boolean;
    onSlotSelect: (slot: TimeSlot) => void;
    disabled?: boolean;
}) {
    const [isHovered, setIsHovered] = useState(false);

    return (
        <button
            className="p-2 rounded-sm pr-4 pl-4"
            onMouseEnter={disabled ? undefined : () => setIsHovered(true)}
            onMouseLeave={disabled ? undefined : () => setIsHovered(false)}
            onClick={disabled ? undefined : () => onSlotSelect(slot)}
            style={{
                ...(disabled
                    ? {
                          opacity: 0.5,
                          backgroundColor: "rgba(52, 94, 178, 0.1)",
                          cursor: "default",
                      }
                    : selectableItemStyle(true, true, isSelected, isHovered)),
                padding: "0.5rem 0.75rem",
                borderRadius: "0.375rem",
            }}
        >
            {slot.start}
            {slot.end && ` - ${slot.end}`}
        </button>
    );
}

function formatDatetime(date: CalendarDate | null, slot: TimeSlot | null): string {
    if (date === null && slot === null) {
        return "";
    }

    let formattedDate, formattedTime;
    if (date !== null) {
        formattedDate = formatDate(date);
        if (slot === null) {
            return formattedDate;
        }
    }

    if (slot !== null) {
        formattedTime = `${slot.start}${slot.end ? ` - ${slot.end}` : ""}`;
        if (date === null) {
            return formattedTime;
        }
    }

    return `${formattedDate}: ${formattedTime}`;
}

function formatDate(date: CalendarDate): string {
    const dateObj = new Date(date.year, date.month - 1, date.day);
    const formatter = new Intl.DateTimeFormat(navigator.language, {
        weekday: "long",
        year: "numeric",
        month: "long",
        day: "numeric",
    });
    return formatter.format(dateObj);
}

